  tools.exec_command({cmd:"pwd",max_output_tokens:1000}),
  tools.exec_command({cmd:"git rev-parse --show-toplevel",max_output_tokens:1000})
]);
for (let i=0;i<results.length;i++) text({command:i===0?"pwd":"git rev-parse --show-toplevel",result:results[i]});
text({command:"entire status --json",result:await tools.exec_command({cmd:"entire status --json",max_output_tokens:4000})});

const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd\n git rev-parse --show-toplevel\n git status --short\n if [ -f AGENTS.md ]; then cat AGENTS.md; fi",max_output_tokens:9000}),
  tools.exec_command({cmd:"cat /Users/johnlee/.agents/skills/commit-provenance/SKILL.md",max_output_tokens:6000})
]);
results.forEach((r,i)=>text({read:i,result:r}));

